data class TypeRoleToken(
    val fontKey: String,
    val weight: Int,
    val italic: Boolean,
    /** sp */
    val size: Float,
    /** multiple of size */
    val lineHeight: Float,
    /** em */
    val tracking: Float,
    val uppercase: Boolean,
    val tabular: Boolean,
) {
    val family: FontFamily get() = RommioFontFamilies.byKey(fontKey)
    val fontWeight: FontWeight get() = FontWeight(weight)
    val fontStyle: FontStyle get() = if (italic) FontStyle.Italic else FontStyle.Normal
}

